import { MESSAGE_TYPES } from './constants';
import { isRtlEnvironment } from './utils/LocaleUtils';
import './ui/common/styles/iframePopup.scss';

class VideoDownloaderIframePopup {
  private static IFRAME_ID = 'video-downloader-extn-iframe';
  private iframe: HTMLIFrameElement | null = null;

  /**
   * Injects the popup iframe into the page.
   */
  injectIframePopup() {
    const span = document.createElement('span');
    span.id = VideoDownloaderIframePopup.IFRAME_ID + '-wrap';
    span.className = 'video-downloader-iframe-wrap';
    
    // Decide left/right placement only
    const isRtl = isRtlEnvironment();
    if (isRtl) {
      // Add RTL class to iframe wrapper for positioning
      span.classList.add('rtl');
    }
    
    span.style.opacity = '0'; // Only opacity is set dynamically

    this.iframe = document.createElement('iframe');
    this.iframe.id = VideoDownloaderIframePopup.IFRAME_ID;
    this.iframe.className = 'video-downloader-iframe';
    this.iframe.src = chrome.runtime.getURL('views/iframePopup.html');
    this.iframe.style.height = 'auto'; // Height is set dynamically

    span.appendChild(this.iframe);
    document.body.appendChild(span);
    setTimeout(() => { span.style.opacity = '1'; }, 10);
    setTimeout(() => { 
      document.addEventListener('mousedown', this.handleClickOutside, true);
      window.addEventListener('resize', this.updateIframeHeight);
    }, 50);
  }

  /**
   * Removes the popup iframe from the page.
   */
  removeIframePopup = () => {
    const span = document.getElementById(VideoDownloaderIframePopup.IFRAME_ID + '-wrap');
    if (span) {
      span.remove();
    }
    this.iframe = null;
    document.removeEventListener('mousedown', this.handleClickOutside, true);
    window.addEventListener('resize', this.updateIframeHeight);
  };

  /**
   * Handles clicks outside the popup to close it.
   */
  handleClickOutside = (e: MouseEvent) => {
    const span = document.getElementById(VideoDownloaderIframePopup.IFRAME_ID + '-wrap');
    if (!span) return;
    if (!span.contains(e.target as Node)) {
      this.removeIframePopup();
    }
  };

  /**
   * Updates Iframe height on resize.
   */
  updateIframeHeight = () => {
    const parentWindowHeight = window.parent.innerHeight;
    this.iframe.style.maxHeight = (parentWindowHeight * 0.8) + 'px'; // 80% of parent window
  }

  /**
   * Handles messages from the background/content script.
   */
  handleRuntimeMessage = (msg: any, sender: any, sendResponse: any) => {
    if (msg && msg.type === MESSAGE_TYPES.TOGGLE_IFRAME_POPUP) {
      const span = document.getElementById(VideoDownloaderIframePopup.IFRAME_ID + '-wrap');
      if (span) {
        this.removeIframePopup();
        sendResponse && sendResponse({ closed: true });
      } else {
        this.injectIframePopup();
        sendResponse && sendResponse({ opened: true });
      }
      return true;
    }

    if (msg && msg.type === MESSAGE_TYPES.SET_IFRAME_POPUP_HEIGHT && this.iframe) {
      this.iframe.style.height = msg.height + 'px';
      const parentHeight = window.parent.innerHeight;
      this.iframe.style.maxHeight = (parentHeight * 0.9) + 'px'; // 90% of parent window
      return true;
    }
  };

  /**
   * Initializes the content script listeners.
   */
  init() {
    chrome.runtime.onMessage.addListener(this.handleRuntimeMessage);
    window.addEventListener('beforeunload', () => this.removeIframePopup());
  }
}

// Initialize the popup manager
const videoDownloaderIframePopup = new VideoDownloaderIframePopup();
videoDownloaderIframePopup.init();
