
import { RTL_LANGUAGES } from "../constants";
/**
 * Determines whether the environment should be treated as RTL.
 * Checks document direction first, then browser language.
 */
export function isRtlEnvironment(): boolean {
  // Check primary browser language as fallback
  const lang = navigator.language?.toLowerCase() || '';
  return RTL_LANGUAGES.some(rtlCode => lang.startsWith(rtlCode));
}


